import zipfile
import xml.etree.ElementTree as ET
import re

NS = {'m': 'http://schemas.openxmlformats.org/officeDocument/2006/main'}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx - 1

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Archive entries:")
    for n in names:
        print(" ", n)

    # Workbook -> sheet name to rId mapping
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rid_to_target = {rel.get('Id'): rel.get('Target') for rel in rels_root}

    sheet_map = {}
    for sh in wb_root.find('m:sheets', NS):
        sheet_map[sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')] = sh.get('name')

    shared_strings = []
    if 'xl/sharedStrings.xml' in names:
        ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss_root.findall('m:si', NS):
            texts = [t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/officeDocument/2006/main}t')]
            shared_strings.append(''.join(texts))

    for rid, sheet_name in sheet_map.items():
        target = rid_to_target[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        path = target if target in names else 'xl/' + target
        root = ET.fromstring(z.read(path))
        print(f"\n=== Sheet: {sheet_name} ===")
        rows = []
        for row in root.find('m:sheetData', NS):
            row_data = {}
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = None
                if v is not None and v.text is not None:
                    if t == 's':
                        val = shared_strings[int(v.text)]
                    elif t == 'b':
                        val = v.text == '1'
                    elif t == 'str':
                        val = v.text
                    else:
                        val = v.text
                is_formula = c.find('m:f', NS) is not None
                row_data[col_to_idx(ref)] = (val, is_formula)
            rows.append(row_data)
        maxc = max((max(r.keys()) for r in rows), default=-1) + 1
        for i, r in enumerate(rows, start=1):
            line = []
            for j in range(maxc):
                item = r.get(j)
                if item is None:
                    line.append('')
                else:
                    val, isf = item
                    if isf:
                        f = r.get(j)[0]
                        line.append(f'[F]{val}')
                    else:
                        line.append(str(val))
            print(f"row {i}: " + " | ".join(line))

